@Component("bOM-entity-projector")
public class BOMEntityProjector implements EntityProjector<BOM>{
		
	// core constructor
	public BOMEntityProjector(ProjectorRegistry registry,
										BOMRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<BOM> getEntityClass() {
		return BOM.class;
	}

    /*
	 * Insert a BOM
	 * 
     * @param	entity BOM
     */
    public BOM create( BOM entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a BOM
	 * 
     * @param	entity BOM
     */
    public BOM update( BOM entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a BOM
	 * 
     * @param	id		UUID
     */
    public BOM delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    BOM entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a ParentItem
     * 
     * @param	parentId	UUID
     * @param	assignment 	Item 
     * @return	BOM
     */
    public BOM assignParentItem( UUID parentId, Item assignment ) {
	    LOGGER.info("assigning ParentItem as " + assignment.toString() );

	    BOM parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Item.class, assignment.getItemId());

	    // ------------------------------------------
		// assign the ParentItem to the parent entity
		// ------------------------------------------ 
	    parentEntity.setParentItem( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the ParentItem
	 * 
	 * @param	parentId		UUID
	 * @return	BOM
	 */
	public BOM unAssignParentItem( UUID parentId ) {
		BOM parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning ParentItem on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the ParentItem on the parent entithy
		// ------------------------------------------     
	    parentEntity.setParentItem(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the BomItems
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	BOM
     */
    public BOM addToBomItems( UUID parentId, BOMItem addTo ) {
	    LOGGER.info("handling AssignBomItemsToBOMEvent - " );
	    
	    BOM parentEntity = repository.findById(parentId).get();
	    BOMItem child = registry.project( BOMItem.class, addTo.getBOMItemId());
	    
	    parentEntity.getBomItems().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the BomItems
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	BOM
     */
	public BOM removeFromBomItems( UUID parentId, BOMItem removeFrom ) {
	    LOGGER.info("handling RemoveBomItemsFromBOMEvent " );
	
	    BOM parentEntity = repository.findById(parentId).get();
	    BOMItem child = registry.project( BOMItem.class, removeFrom.getBOMItemId());
	    
	    parentEntity.getBomItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the BOM via an FindBOMQuery
     * @return 	query	FindBOMQuery
     */
    @SuppressWarnings("unused")
    public BOM find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a BOM - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all BOMs
     *
     * @param	query	FindAllBOMQuery 
     * @return 	List<BOM> 
     */
    @SuppressWarnings("unused")
    public List<BOM> findAll( FindAllBOMQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all BOM - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final BOMRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(BOMEntityProjector.class.getName());

}
